import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import {
  listConversations,
  getConversation,
  getConversationMessages,
  getClientBookingsSummary,
} from '@/lib/messaging/queries'
import { markConversationRead } from '@/lib/messaging/mutations'
import { MessagesShell } from '@/components/messages/MessagesShell'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'

export const metadata: Metadata = {
  title: 'Messages — InkOS',
}

export default async function MessagesPage() {
  let studioId: string

  try {
    const ctx = await getActiveStudio()
    studioId = ctx.studioId
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { conversations } = await listConversations(studioId, {
    limit: 50,
    archived: false,
  })

  // Auto-select the most recent conversation (desktop convenience;
  // mobile MessagesShell shows the list only and navigates on tap).
  const firstConversation = conversations[0] ?? null
  const activeConversationId = firstConversation?.id ?? null

  let activeConversation = null
  let activeMessages: Awaited<ReturnType<typeof getConversationMessages>> = []
  let recentBookings: Awaited<ReturnType<typeof getClientBookingsSummary>> = []

  if (activeConversationId) {
    activeConversation = await getConversation(studioId, activeConversationId)

    if (activeConversation) {
      const [msgs, bookings] = await Promise.all([
        getConversationMessages(studioId, activeConversationId, { limit: 50 }),
        activeConversation.client
          ? getClientBookingsSummary(studioId, activeConversation.client.id, 3)
          : Promise.resolve([]),
      ])
      activeMessages = msgs
      recentBookings = bookings

      if (activeConversation.unread_count > 0) {
        await markConversationRead(studioId, activeConversationId)
      }
    }
  }

  return (
    <PageShell fullHeight>
      <div className="px-4 py-4 sm:px-6 lg:px-8 shrink-0">
        <PageHeader
          title="Messages"
          description="SMS and email conversations with clients"
        />
      </div>
      <div className="flex-1 min-h-0">
        <MessagesShell
          conversations={conversations}
          activeConversation={activeConversation}
          activeMessages={activeMessages}
          recentBookings={recentBookings}
          studioId={studioId}
          activeConversationId={activeConversationId ?? undefined}
        />
      </div>
    </PageShell>
  )
}

'use client'

/**
 * MessagesShell — 2-pane layout wrapper.
 *
 * Desktop: left rail (360px threads) + right (thread panel + client sidebar)
 * Mobile: thread list is default view; tapping a thread navigates to /messages/[id]
 *
 * This component is "use client" only for the isMobile detection;
 * both children are server-rendered (passed as props).
 */

import { useIsMobile } from '@/hooks/useIsMobile'
import type { ConversationWithClient, ConversationMessage, ClientBookingSummary } from '@/lib/messaging/queries'
import { ThreadList } from './ThreadList'
import { ThreadPanel } from './ThreadPanel'
import { MessageSquare } from 'lucide-react'

// ─── Types ────────────────────────────────────────────────────────────────────

interface MessagesShellProps {
  conversations: ConversationWithClient[]
  activeConversation?: ConversationWithClient | null
  activeMessages?: ConversationMessage[]
  recentBookings?: ClientBookingSummary[]
  studioId: string
  activeConversationId?: string | undefined
}

// ─── MessagesShell ────────────────────────────────────────────────────────────

export function MessagesShell({
  conversations,
  activeConversation,
  activeMessages = [],
  recentBookings = [],
  studioId,
  activeConversationId,
}: MessagesShellProps) {
  const isMobile = useIsMobile()

  // On mobile: if we have an active conversation, show only the thread panel
  if (isMobile && activeConversation) {
    return (
      <div className="h-full">
        <ThreadPanel
          conversation={activeConversation}
          initialMessages={activeMessages}
          recentBookings={recentBookings}
          showBackButton
        />
      </div>
    )
  }

  // On mobile without active conversation: show only thread list
  if (isMobile) {
    return (
      <div className="h-full">
        <ThreadList
          conversations={conversations}
          studioId={studioId}
          activeConversationId={activeConversationId}
        />
      </div>
    )
  }

  // Desktop: 2-pane layout
  return (
    <div className="flex h-full overflow-hidden">
      {/* Left rail — thread list */}
      <div className="w-[360px] shrink-0 border-r border-border flex flex-col overflow-hidden">
        <ThreadList
          conversations={conversations}
          studioId={studioId}
          activeConversationId={activeConversationId}
        />
      </div>

      {/* Right — thread panel or empty state */}
      <div className="flex-1 min-w-0 overflow-hidden">
        {activeConversation ? (
          <ThreadPanel
            conversation={activeConversation}
            initialMessages={activeMessages}
            recentBookings={recentBookings}
          />
        ) : (
          <EmptyThreadState hasConversations={conversations.length > 0} />
        )}
      </div>
    </div>
  )
}

// ─── EmptyThreadState ─────────────────────────────────────────────────────────

function EmptyThreadState({ hasConversations }: { hasConversations: boolean }) {
  return (
    <div className="flex flex-col items-center justify-center h-full text-center px-8">
      <div className="h-14 w-14 rounded-2xl bg-primary/10 flex items-center justify-center mb-4">
        <MessageSquare className="h-7 w-7 text-primary" aria-hidden />
      </div>
      <h2 className="font-semibold text-foreground mb-1">
        {hasConversations ? 'Select a conversation' : 'No messages yet'}
      </h2>
      <p className="text-sm text-muted-foreground max-w-xs">
        {hasConversations
          ? 'Choose a conversation from the left to view messages.'
          : 'When clients message you via SMS or email, their conversations will appear here.'}
      </p>
    </div>
  )
}

/**
 * Messaging queries — server-side only (Server Components + Server Actions).
 *
 * All queries enforce studio_id scoping.
 * Uses the authenticated (anon key + session) client — RLS enforces access.
 */

import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import type { Conversation, ConversationChannel } from '@/lib/supabase/types'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ClientSummary {
  id: string
  first_name: string
  last_name: string | null
  email: string | null
  phone: string | null
  avatar_url: string | null
  total_spent_cents: number
  total_sessions: number
}

export interface ConversationWithClient extends Conversation {
  client: ClientSummary | null
}

export interface ConversationMessage {
  id: string
  conversation_id: string | null
  channel: 'email' | 'sms' | 'whatsapp' | 'in_app'
  direction: 'outbound' | 'inbound'
  subject: string | null
  body: string
  status: 'queued' | 'sent' | 'delivered' | 'opened' | 'clicked' | 'failed' | 'bounced'
  sent_at: string | null
  delivered_at: string | null
  opened_at: string | null
  error: string | null
  provider_message_id: string | null
  metadata: Record<string, unknown>
  created_at: string
  updated_at: string
}

export interface ListConversationsFilters {
  channel?: ConversationChannel
  unreadOnly?: boolean
  assignedToMe?: boolean
  search?: string
  archived?: boolean
  limit?: number
  offset?: number
}

export interface ListConversationsResult {
  conversations: ConversationWithClient[]
  total: number
}

// ─── listConversations ────────────────────────────────────────────────────────

export async function listConversations(
  studioId: string,
  filters: ListConversationsFilters = {},
): Promise<ListConversationsResult> {
  const supabase = await createClient()
  const limit = filters.limit ?? 50
  const offset = filters.offset ?? 0

  let query = supabase
    .from('conversations')
    .select(
      `
      *,
      client:clients (
        id, first_name, last_name, email, phone,
        total_spent_cents, total_sessions
      )
    `,
      { count: 'exact' },
    )
    .eq('studio_id', studioId)
    .order('last_message_at', { ascending: false, nullsFirst: false })
    .range(offset, offset + limit - 1)

  // Archived / active filter
  if (filters.archived === true) {
    query = query.not('archived_at', 'is', null)
  } else {
    query = query.is('archived_at', null)
  }

  if (filters.channel) {
    query = query.eq('channel', filters.channel)
  }

  if (filters.unreadOnly) {
    query = query.gt('unread_count', 0)
  }

  if (filters.search) {
    // Search against display_name or external_identifier
    query = query.or(
      `display_name.ilike.%${filters.search}%,external_identifier.ilike.%${filters.search}%`,
    )
  }

  const { data, error, count } = await query

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: listConversations failed')
    return { conversations: [], total: 0 }
  }

  return {
    conversations: (data ?? []) as ConversationWithClient[],
    total: count ?? 0,
  }
}

// ─── getConversation ──────────────────────────────────────────────────────────

export async function getConversation(
  studioId: string,
  conversationId: string,
): Promise<ConversationWithClient | null> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('conversations')
    .select(
      `
      *,
      client:clients (
        id, first_name, last_name, email, phone,
        total_spent_cents, total_sessions
      )
    `,
    )
    .eq('id', conversationId)
    .eq('studio_id', studioId)
    .single()

  if (error || !data) {
    if (error?.code !== 'PGRST116') {
      logger.error({ err: error, conversationId }, 'messaging: getConversation failed')
    }
    return null
  }

  return data as ConversationWithClient
}

// ─── getConversationMessages ──────────────────────────────────────────────────

export async function getConversationMessages(
  studioId: string,
  conversationId: string,
  opts: { limit?: number; before?: string } = {},
): Promise<ConversationMessage[]> {
  const supabase = await createClient()
  const limit = opts.limit ?? 50

  let query = supabase
    .from('client_communications')
    .select('id, conversation_id, channel, direction, subject, body, status, sent_at, delivered_at, opened_at, error, provider_message_id, metadata, created_at, updated_at')
    .eq('studio_id', studioId)
    .eq('conversation_id', conversationId)
    .order('created_at', { ascending: false })
    .limit(limit)

  if (opts.before) {
    query = query.lt('created_at', opts.before)
  }

  const { data, error } = await query

  if (error) {
    logger.error({ err: error, conversationId }, 'messaging: getConversationMessages failed')
    return []
  }

  // Return oldest-first for rendering (reverse the DESC query result)
  return ((data ?? []) as ConversationMessage[]).reverse()
}

// ─── searchMessages ───────────────────────────────────────────────────────────

export async function searchMessages(
  studioId: string,
  query: string,
): Promise<ConversationMessage[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('client_communications')
    .select('id, conversation_id, channel, direction, subject, body, status, sent_at, delivered_at, opened_at, error, provider_message_id, metadata, created_at, updated_at')
    .eq('studio_id', studioId)
    .or(`body.ilike.%${query}%,subject.ilike.%${query}%`)
    .order('created_at', { ascending: false })
    .limit(50)

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: searchMessages failed')
    return []
  }

  return (data ?? []) as ConversationMessage[]
}

// ─── getUnreadConversationCount ───────────────────────────────────────────────

export async function getUnreadConversationCount(studioId: string): Promise<number> {
  const supabase = await createClient()

  const { count, error } = await supabase
    .from('conversations')
    .select('id', { count: 'exact', head: true })
    .eq('studio_id', studioId)
    .gt('unread_count', 0)
    .is('archived_at', null)

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: getUnreadConversationCount failed')
    return 0
  }

  return count ?? 0
}

// ─── getClientBookingsSummary ─────────────────────────────────────────────────
// Used by ClientContextCard to show quick stats

export interface ClientBookingSummary {
  id: string
  scheduled_at: string | null
  status: string
  service_name: string | null
  price_cents: number
}

export async function getClientBookingsSummary(
  studioId: string,
  clientId: string,
  limit = 3,
): Promise<ClientBookingSummary[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('bookings')
    .select('id, scheduled_at, status, price_cents, services(name)')
    .eq('studio_id', studioId)
    .eq('client_id', clientId)
    .order('scheduled_at', { ascending: false })
    .limit(limit)

  if (error) {
    logger.error({ err: error, clientId }, 'messaging: getClientBookingsSummary failed')
    return []
  }

  return (data ?? []).map((b) => ({
    id: b.id,
    scheduled_at: b.scheduled_at,
    status: b.status,
    price_cents: b.price_cents,
    service_name: Array.isArray(b.services)
      ? (b.services[0] as { name: string } | undefined)?.name ?? null
      : (b.services as { name: string } | null)?.name ?? null,
  }))
}

